update public.spell_catalog set name_ru='Удержание монстра', casting_time='Действие', spell_range='90 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='прямой кусок железа', check_type='Спасбросок Мудрости; повтор в конце каждого хода', damage='', effect_summary='При провале цель становится Парализованной. В конце каждого своего хода повторяет спасбросок и при успехе заканчивает эффект на себе.', upcast='+1 цель за каждый уровень ячейки выше 5.', notes='Работает на существо любого типа, если иное не ограничено иммунитетами цели.', author_description='Версия Удержания личности для тех случаев, когда проблема перестала быть гуманоидом и стала значительно крупнее.', author_comment='Парализованный монстр выглядит гораздо менее легендарно. Пользуйся моментом.' where slug='hold-monster';
update public.spell_catalog set name_ru='Нашествие насекомых', casting_time='Действие', spell_range='300 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='саранча', check_type='Спасбросок Телосложения; не чаще 1 раза за ход на существо', damage='4к10 колющего; половина при успехе', effect_summary='Сфера роившейся саранчи является слегка заслонённой и труднопроходимой. Существа делают спасбросок при появлении роя, первом входе за ход или окончании хода внутри.', upcast='+1к10 урона за каждый уровень ячейки выше 5.', notes='Одно существо делает этот спасбросок не чаще одного раза за ход.', author_description='Триста футов дальности и двадцать футов саранчи. Иногда природа не нуждается в тонких намёках.', author_comment='Если после этого кто-то предлагает пикник, его нужно проверить на Очарование.' where slug='insect-plague';
update public.spell_catalog set name_ru='Знание легенд', casting_time='10 минут', spell_range='На себя', area='Известная или описанная знаменитая личность, место или предмет', duration='Мгновенно', components=array['В','С','М'], material='ладан стоимостью 250+ зм, расходуется, и четыре полоски слоновой кости стоимостью 50+ зм каждая', check_type='', damage='', effect_summary='Получаешь правдивую краткую сводку важного знания о знаменитом человеке, месте или предмете. Чем больше уже знаешь, тем точнее и подробнее ответ. Информация может быть выражена образно или стихами.', upcast='', notes='Если выбранная вещь на самом деле не знаменита, звучат грустные ноты тромбона и заклинание проваливается. Ладан расходуется; слоновая кость не указана как расходуемая.', author_description='Тратишь десять минут и дорогой ладан, чтобы сама магия пересказала тебе справку о знаменитости. Если объект никому не известен, вселенная отвечает грустным тромбоном. Это достойный уровень издевательства.', author_comment='Редкое заклинание, где провал сопровождается официальным саундтреком.' where slug='legend-lore';
update public.spell_catalog set name_ru='Массовое лечение ран', casting_time='Действие', spell_range='60 футов', area='До 6 существ в сфере радиусом 30 футов вокруг видимой точки', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='Лечение: 5к8 + модификатор характеристики заклинаний каждой цели', effect_summary='Выбираешь до шести существ в сфере радиусом 30 футов вокруг видимой точки; каждое восстанавливает 5к8 + модификатор характеристики заклинаний HP.', upcast='+1к8 лечения за каждый уровень ячейки выше 5.', notes='Каждая цель получает полный отдельный бросок лечения по формуле заклинания.', author_description='До шести человек одновременно перестают выглядеть как проблема полевого медика. Жрец опять делает мою старую профессию подозрительно устаревшей.', author_comment='Если после пяти к8 лечения кто-то всё ещё требует перевязку, это уже привычка.' where slug='mass-cure-wounds';
update public.spell_catalog set name_ru='Ложный след', casting_time='Действие', spell_range='На себя', area='Ты и иллюзорный двойник', duration='Концентрация, до 1 часа', components=array['С'], material=null, check_type='', damage='', effect_summary='Ты становишься Невидимым и одновременно создаёшь в своём месте иллюзорного двойника. Действием Магии можно двигать двойника до удвоенной Скорости, заставлять говорить и жестикулировать. Ты можешь видеть его глазами и слышать его ушами.', upcast='', notes='Невидимость заканчивается сразу после броска атаки, нанесения урона или сотворения заклинания, но двойник остаётся до окончания заклинания. Он неосязаем и неуязвим.', author_description='Исчезаешь, оставляешь вместо себя говорящую копию и наблюдаешь её глазами. Наконец способ присутствовать на совещании в правильном объёме.', author_comment='Если двойник общается убедительнее оригинала, не торопись возвращаться.' where slug='mislead';
update public.spell_catalog set name_ru='Изменение памяти', casting_time='Действие', spell_range='30 футов', area='1 видимое существо', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; с преимуществом, если вы сражаетесь', damage='', effect_summary='При провале цель Очарована, Недееспособна и не осознаёт окружение, но слышит тебя. Пока эффект длится, можешь изменить воспоминание об одном событии последних 24 часов длительностью не более 10 минут: удалить, сделать идеально ясным, изменить детали или заменить другим событием.', upcast='Ячейка 6: события до 7 дней назад; 7: до 30 дней; 8: до 365 дней; 9: любое время в прошлом цели.', notes='Если цель получает урон или становится целью другого заклинания, эффект заканчивается без изменения памяти. Нужно закончить словесное описание до конца заклинания, и цель должна понимать язык. Снятие проклятия или Высшее восстановление возвращает настоящую память. Абсурдное воспоминание может не повлиять на поведение.', author_description='Переписываешь десять минут чужой жизни словами. Очень мощная магия, пока не пытаешься убедить человека, что он с удовольствием плавал в кислоте.', author_comment='Память можно изменить. Здравый смысл — куда сложнее.' where slug='modify-memory';
update public.spell_catalog set name_ru='Проход сквозь стену', casting_time='Действие', spell_range='30 футов', area='Проход до 5 футов шириной, 8 высотой и 20 глубиной', duration='1 час', components=array['В','С','М'], material='щепотка семян кунжута', check_type='', damage='', effect_summary='Создаёшь временный проход в видимой деревянной, оштукатуренной или каменной поверхности: стене, потолке или полу. Размеры выбираешь в пределах 5×8×20 футов.', upcast='', notes='Проход не нарушает устойчивость сооружения. Когда он исчезает, оставшиеся внутри существа и предметы безопасно выталкиваются в ближайшее свободное место у поверхности.', author_description='Стена на час соглашается, что она дверь. Архитекторы опять проигрывают магии спор о назначении конструкции.', author_comment='Главное преимущество — заклинание само выталкивает тех, кто решил переждать закрытие внутри.' where slug='passwall';
update public.spell_catalog set name_ru='Планарное связывание', casting_time='1 час', spell_range='60 футов', area='1 Небожитель, Элементаль, Фея или Исчадие', duration='24 часа', components=array['В','С','М'], material='драгоценный камень стоимостью 1000+ зм, расходуется', check_type='Спасбросок Харизмы после полного часа сотворения', damage='', effect_summary='Цель должна оставаться в пределах 60 футов весь час. В конце сотворения при провале спасброска она обязана служить тебе весь срок. Если была призвана или создана другим заклинанием, длительность того заклинания продлевается до длительности связывания.', upcast='Ячейка 6: 10 дней; 7: 30 дней; 8: 180 дней; 9: 366 дней.', notes='Враждебное связанное существо выполняет приказы, но старается толковать их в своих интересах. Обычно цель сначала удерживают инвертированным Магическим кругом.', author_description='Час стоишь рядом с существом из другого мира, сжигаешь тысячу золотых и пытаешься юридически закрепить его в своей команде. Варлоки называют это упущенной возможностью добавить мелкий шрифт.', author_comment='Если связанное исчадие слишком охотно выполняет приказ, перечитай формулировку.' where slug='planar-binding';
update public.spell_catalog set name_ru='Воскрешение мёртвого', casting_time='1 час', spell_range='Касание', area='1 существо, умершее не более 10 дней назад', duration='Мгновенно', components=array['В','С','М'], material='алмаз стоимостью 500+ зм, расходуется', check_type='', damage='Возвращает с 1 HP', effect_summary='Возвращаешь к жизни существо, умершее не более 10 дней назад и не бывшее Нежитью в момент смерти. Оно возвращается с 1 HP; яды, действовавшие в момент смерти, нейтрализуются. Смертельные раны закрываются.', upcast='', notes='Не восстанавливает отсутствующие части тела; если не хватает жизненно важной части или органа, например головы, заклинание проваливается. После возвращения цель получает −4 ко всем испытаниям к20; после каждого долгого отдыха штраф уменьшается на 1 до 0.', author_description='Час, пятьсот золотых и человек снова жив. Но возвращается с одним HP и таким видом, будто смерть выставила ему счёт за досрочный выезд.', author_comment='Алмаз расходуется. Травма от возвращения — тоже, но медленнее.' where slug='raise-dead';
update public.spell_catalog set name_ru='Реинкарнация', casting_time='1 час', spell_range='Касание', area='Мёртвый гуманоид или часть его тела, смерть не более 10 дней назад', duration='Мгновенно', components=array['В','С','М'], material='редкие масла стоимостью 1000+ зм, расходуются', check_type='Для нового вида: бросок 1к10 либо выбор Мастера другого игрового вида', damage='', effect_summary='Формируешь для умершего гуманоида новое тело и призываешь душу войти в него. Существо помнит прошлую жизнь и сохраняет прежние способности, но теряет черты старого вида и получает черты нового.', upcast='', notes='Официальная таблица SRD 5.2.1: 1 — переброс; 2 Драконорождённый; 3 Дварф; 4 Эльф; 5 Гном; 6 Голиаф; 7 Полурослик; 8 Человек; 9 Орк; 10 Тифлинг. Мастер может выбрать другой игровой вид.', author_description='Тысяча золотых масел, час работы и покойник получает новое тело. Иногда смерть — не конец, а крайне агрессивный редактор внешности.', author_comment='Если выпал тот же вид, считай, что вселенная просто взяла комиссию.' where slug='reincarnate';
update public.spell_catalog set name_ru='Наблюдение', casting_time='10 минут', spell_range='На себя', area='1 существо на том же плане или знакомое место', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='фокус стоимостью 1000+ зм: например хрустальный шар, зеркало или наполненная водой купель', check_type='Цель делает спасбросок Мудрости с модификаторами знания и связи', damage='', effect_summary='При провале создаёшь невидимый неосязаемый сенсор в 10 футах от цели и видишь/слышишь через него; сенсор следует за целью. Вместо существа можно наблюдать место, которое ты видел — тогда сенсор неподвижен.', upcast='', notes='Модификатор спасброска по знакомству: слышал +5, встречал +0, хорошо знаешь −5. Связь: изображение −2, вещь цели −4, часть тела/волос/ноготь −10. При успешном спасброске цель не затронута, и повторно наблюдать её этим заклинанием нельзя 24 часа. Цель не знает причину броска.', author_description='Десять минут подготовки и тысяча золотых за оборудование, чтобы профессионально подглядывать за кем-то через магический шар.', author_comment='Если у тебя есть его ноготь, проблема конфиденциальности началась задолго до заклинания.' where slug='scrying';
update public.spell_catalog set name_ru='Маскарад', casting_time='Действие', spell_range='30 футов', area='Любое число выбранных видимых существ', duration='8 часов', components=array['В','С'], material=null, check_type='Нежелающая цель: спасбросок Харизмы; распознавание: Интеллект (Расследование) против Сл заклинаний', damage='', effect_summary='Меняешь иллюзорный внешний вид тел и снаряжения выбранных существ. Можно сделать каждого до 1 фута выше или ниже, тяжелее или легче на вид, но базовое расположение конечностей должно сохраняться.', upcast='', notes='Физическая проверка выдаёт иллюзию: предметы проходят сквозь несуществующие детали. Успешное Изучение позволяет понять, что цель замаскирована.', author_description='На восемь часов вся группа может выглядеть как совершенно другие люди. Плуты называют это логистикой.', author_comment='Иллюзорная шляпа не останавливает руку. Мода снова подвела.' where slug='seeming';
update public.spell_catalog set name_ru='Призыв дракона', casting_time='Действие', spell_range='60 футов', area='1 свободное место', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='предмет с выгравированным изображением дракона стоимостью 500+ зм', check_type='', damage='По блоку характеристик Драконьего духа', effect_summary='Призываешь Драконий дух с отдельным блоком характеристик. Он союзник, делит с тобой инициативу, ходит сразу после тебя и выполняет словесные команды без траты твоего действия. Без приказа Уклоняется и избегает опасности.', upcast='Уровень потраченной ячейки используется как уровень заклинания в блоке характеристик Драконьего духа.', notes='Дух исчезает при 0 HP или окончании заклинания.', author_description='Пятый круг: волшебник наконец может вызвать дракона, не убеждая настоящего дракона, что это хорошая идея.', author_comment='Если дух слушается команд — наслаждайся. С настоящими драконами этот этап обычно отсутствует.' where slug='summon-dragon';
update public.spell_catalog set name_ru='Телекинез', casting_time='Действие', spell_range='60 футов', area='1 видимое существо или объект за применение', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Существо или переносимый предмет: спасбросок Силы', damage='', effect_summary='При наложении и действием Магии в следующие ходы выбираешь видимое Огромное или меньшее существо/предмет. Существо при провале перемещается до 30 футов и становится Опутанным до конца твоего следующего хода; поднятое в воздух падает, если эффект не продлить. Непереносимый предмет перемещается автоматически до 30 футов.', upcast='', notes='Если переключаешься на новую цель, предыдущая больше не затронута. Переносимый предмет можно вырвать при провале спасброска владельца. Допускается точное манипулирование простым инструментом, дверью, контейнером или содержимым флакона.', author_description='Двигаешь людей и предметы мыслью. Волшебники наконец нашли способ не вставать со стула даже во время похищения.', author_comment='Если дверь можно открыть телекинезом, плут временно становится предметом интерьера.' where slug='telekinesis';
update public.spell_catalog set name_ru='Телепатическая связь', casting_time='Действие или ритуал', spell_range='30 футов', area='До 8 добровольных существ', duration='1 час', components=array['В','С','М'], material='два яйца', check_type='', damage='', effect_summary='До восьми добровольных существ образуют общую телепатическую сеть. Все цели могут мысленно общаться друг с другом на любом расстоянии, даже без общего языка.', upcast='', notes='Не действует на существ, которые вообще не способны общаться ни на одном языке. Связь не проходит между разными планами существования.', author_description='Восемь человек получают общий мысленный чат на час. Через пять минут кто-нибудь обязательно использует его для того, что можно было не думать вслух.', author_comment='Два яйца как компонент. Видимо, магия заранее оценила качество группового общения.' where slug='telepathic-bond';
update public.spell_catalog set name_ru='Круг телепортации', casting_time='1 минута', spell_range='10 футов', area='Круг радиусом 5 футов', duration='1 раунд', components=array['В','М'], material='редкие чернила стоимостью 50+ зм, расходуются', check_type='', damage='', effect_summary='Рисуешь круг, соединённый с известным тебе постоянным кругом телепортации на том же плане. Портал остаётся до конца твоего следующего хода; вошедшее существо мгновенно появляется в 5 футах от круга назначения или ближайшем свободном месте.', upcast='', notes='При первом получении этого заклинания узнаёшь последовательности сигилов двух мест на Материальном плане по выбору Мастера. Новую последовательность можно запомнить после 1 минуты изучения. Ежедневное наложение в одном месте 365 дней создаёт постоянный круг.', author_description='Минута рисования дорогими чернилами — и у тебя есть портал к известному постоянному кругу. Железные дороги нервно курят в стороне.', author_comment='Пятьдесят золотых за поездку без багажа и задержек. Подозрительно выгодно.' where slug='teleportation-circle';
update public.spell_catalog set name_ru='Шаг через деревья', casting_time='Действие', spell_range='На себя', area='Живые деревья одного вида в пределах 500 футов', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Можешь войти в живое дерево своего размера или больше, потратив 5 футов движения, мгновенно узнать все деревья того же вида в 500 футах и выйти из выбранного, потратив ещё 5 футов движения.', upcast='', notes='Телепортацию можно использовать только один раз за каждый свой ход. Нужно заканчивать каждый ход снаружи дерева. Если движения для выхода не осталось, появляешься рядом с исходным деревом.', author_description='Друид превращает лес в сеть дверей. Следопыт просто молча пользуется маршрутом и не спрашивает, почему дубы теперь транспорт.', author_comment='Главное правило: закончи ход снаружи дерева. Оно тоже не хочет тебя оставлять.' where slug='tree-stride';
update public.spell_catalog set name_ru='Стена силы', casting_time='Действие', spell_range='120 футов', area='Полусфера/сфера радиусом до 10 футов либо 10 соединённых панелей 10×10 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='осколок стекла', check_type='', damage='', effect_summary='Создаёшь невидимую стену силы толщиной 1/4 дюйма любой ориентации. Физически через неё не проходит ничто. Стена иммунна ко всему урону и существует также на Эфирном плане.', upcast='', notes='Если появляется через пространство существа, ты выбираешь сторону, на которую оно выталкивается. Рассеивание магии стену не снимает. Распад уничтожает её мгновенно. Она блокирует эфирное перемещение.', author_description='Невидимая стена, которую нельзя сломать, пробить или рассеять обычной магией. Волшебник наконец создаёт препятствие столь же упрямое, как он сам.', author_comment='Если враг продолжает бить стену, не мешай. Бесплатная психология боя.' where slug='wall-of-force';
update public.spell_catalog set name_ru='Каменная стена', casting_time='Действие', spell_range='120 футов', area='10 соединённых панелей 10×10 футов толщиной 6 дюймов либо 10×20 футов толщиной 3 дюйма', duration='Концентрация, до 10 минут; затем может стать постоянной', components=array['В','С','М'], material='кубик гранита', check_type='Если цель полностью окружается стеной: спасбросок Ловкости для возможности Реакцией уйти', damage='', effect_summary='Создаёшь немагическую стену настоящего камня. Панели должны соединяться, могут образовывать мосты, рампы и грубые укрепления, но должны быть связаны с существующим камнем и иметь опору. Панели можно разрушать.', upcast='', notes='Каждая панель: КД 15, 30 HP за каждый дюйм толщины, иммунитет к яду и психическому урону. Если удерживать концентрацию все 10 минут, стена становится постоянной и уже не может быть рассеяна; иначе исчезает с окончанием заклинания.', author_description='Десять минут концентрации — и магическая проблема превращается в постоянную строительную. Редкий случай, когда волшебник оставляет после себя что-то кроме кратера.', author_comment='Постоянная каменная стена — это уже архитектура. Не говори архитектору, как быстро ты её сделал.' where slug='wall-of-stone';